import { TriviaQuestion } from '../trivia-types'

export const SPORTS_QUESTIONS: TriviaQuestion[] = [
  { id: 'spo-1', category: 'sports', difficulty: 'easy', question: 'What sport is played at the Super Bowl?', answer: 'Football', options: ['Baseball', 'Football', 'Basketball', 'Hockey'], explanation: 'The Super Bowl is the NFL championship game, first played in January 1967. The Green Bay Packers won the first two Super Bowls under coach Vince Lombardi.' },
  { id: 'spo-2', category: 'sports', difficulty: 'easy', question: 'How many players are on a basketball team on the court at one time?', answer: '5', options: ['4', '5', '6', '7'], explanation: 'Each team has 5 players on the court: typically a point guard, shooting guard, small forward, power forward, and center. NBA rosters can have up to 15 players total.' },
  { id: 'spo-3', category: 'sports', difficulty: 'easy', question: 'What country has won the most FIFA World Cup titles?', answer: 'Brazil', options: ['Germany', 'Brazil', 'Italy', 'Argentina'], explanation: 'Brazil has won the World Cup five times (1958, 1962, 1970, 1994, 2002). They are the only team to have played in every World Cup tournament since its inception in 1930.' },
  { id: 'spo-4', category: 'sports', difficulty: 'easy', question: 'What is the maximum score possible in a single frame of bowling?', answer: '30', options: ['10', '20', '30', '300'], explanation: 'A strike is worth 10 pins plus the next two rolls as bonus. If you get three strikes in a row, the first frame scores 30. A perfect game of 12 consecutive strikes totals 300.' },
  { id: 'spo-5', category: 'sports', difficulty: 'easy', question: 'In what sport would you perform a slam dunk?', answer: 'Basketball', options: ['Volleyball', 'Basketball', 'Tennis', 'Football'], explanation: 'A slam dunk involves jumping and pushing the ball directly through the basket from above the rim. The NBA first held a Slam Dunk Contest at the 1984 All-Star Weekend.' },
  { id: 'spo-6', category: 'sports', difficulty: 'easy', question: 'How many periods are in a regulation NHL hockey game?', answer: '3', options: ['2', '3', '4', '5'], explanation: 'NHL games consist of three 20-minute periods. If the game is tied after regulation, it goes to a 5-minute overtime period, followed by a shootout if still tied.' },
  { id: 'spo-7', category: 'sports', difficulty: 'easy', question: 'What is the term for scoring three goals in a single hockey game?', answer: 'Hat trick', options: ['Triple play', 'Hat trick', 'Turkey', 'Trifecta'], explanation: 'The term "hat trick" originated in cricket in 1858 when a bowler was given a hat for taking three wickets on consecutive deliveries. Fans traditionally throw hats onto the ice to celebrate a hockey hat trick.' },
  { id: 'spo-8', category: 'sports', difficulty: 'easy', question: 'What sport does Tiger Woods play?', answer: 'Golf', options: ['Tennis', 'Golf', 'Cricket', 'Polo'], explanation: 'Tiger Woods has won 15 major championships and 82 PGA Tour events, tied for the all-time record with Sam Snead. He is widely considered one of the greatest golfers of all time.' },
  { id: 'spo-9', category: 'sports', difficulty: 'easy', question: 'How many bases are there on a baseball diamond?', answer: '4', options: ['3', '4', '5', '6'], explanation: 'The four bases are first base, second base, third base, and home plate. The distance between each base in Major League Baseball is 90 feet.' },
  { id: 'spo-10', category: 'sports', difficulty: 'easy', question: 'What color jersey does the leader of the Tour de France wear?', answer: 'Yellow', options: ['Green', 'Yellow', 'Red', 'White'], explanation: 'The yellow jersey (maillot jaune) has been awarded to the overall race leader since 1919. The green jersey goes to the best sprinter, and the polka dot jersey to the best climber.' },
  { id: 'spo-11', category: 'sports', difficulty: 'easy', question: 'What NFL team is known as "America\'s Team"?', answer: 'Dallas Cowboys', options: ['New England Patriots', 'Dallas Cowboys', 'Green Bay Packers', 'Pittsburgh Steelers'], explanation: 'The Dallas Cowboys earned this nickname from a 1978 NFL Films highlight video. They have won five Super Bowls (VI, XII, XXVII, XXVIII, XXX) and are one of the most valuable sports franchises in the world.' },
  { id: 'spo-12', category: 'sports', difficulty: 'easy', question: 'How many rings are on the Olympic flag?', answer: '5', options: ['4', '5', '6', '7'], explanation: 'The five rings represent the five continents participating in the Olympics: Africa, the Americas, Asia, Europe, and Oceania. The rings are blue, yellow, black, green, and red on a white background.' },
  { id: 'spo-13', category: 'sports', difficulty: 'easy', question: 'What is the highest possible break in snooker?', answer: '147', options: ['127', '135', '147', '155'], explanation: 'A maximum break of 147 requires potting all 15 reds with blacks, then all six colors in order. Ronnie O\'Sullivan holds the record for the fastest maximum break at 5 minutes 8 seconds.' },
  { id: 'spo-14', category: 'sports', difficulty: 'easy', question: 'What sport is played at Wimbledon?', answer: 'Tennis', options: ['Cricket', 'Tennis', 'Golf', 'Rugby'], explanation: 'Wimbledon is the oldest tennis tournament in the world, first held in 1877. It is the only Grand Slam still played on grass courts and is known for its strict all-white dress code.' },
  { id: 'spo-15', category: 'sports', difficulty: 'easy', question: 'What NBA player is nicknamed "King James"?', answer: 'LeBron James', options: ['Michael Jordan', 'LeBron James', 'Kobe Bryant', 'Kevin Durant'], explanation: 'LeBron James earned the nickname as a high school phenom in Akron, Ohio. He became the NBA\'s all-time leading scorer in 2023, surpassing Kareem Abdul-Jabbar\'s record of 38,387 points.' },
  { id: 'spo-16', category: 'sports', difficulty: 'easy', question: 'What is a "birdie" in golf?', answer: 'One stroke under par', options: ['One stroke over par', 'One stroke under par', 'Two strokes under par', 'Even with par'], explanation: 'The term "birdie" originated in the United States in 1899. An eagle is two under par, and an albatross (double eagle) is three under par.' },
  { id: 'spo-17', category: 'sports', difficulty: 'easy', question: 'How many points is a touchdown worth in football?', answer: '6', options: ['5', '6', '7', '8'], explanation: 'A touchdown is worth 6 points, with the option to kick an extra point (1 point) or attempt a two-point conversion. The term "touchdown" comes from the original rule requiring the ball to be touched to the ground.' },
  { id: 'spo-18', category: 'sports', difficulty: 'easy', question: 'What boxer was known as "The Greatest"?', answer: 'Muhammad Ali', options: ['Mike Tyson', 'Muhammad Ali', 'Sugar Ray Leonard', 'Floyd Mayweather'], explanation: 'Muhammad Ali (born Cassius Clay) won the heavyweight title three times and had a career record of 56-5. His famous quote was "Float like a butterfly, sting like a bee."' },
  { id: 'spo-19', category: 'sports', difficulty: 'easy', question: 'What is the national sport of Canada?', answer: 'Lacrosse', options: ['Hockey', 'Lacrosse', 'Curling', 'Football'], explanation: 'Lacrosse was declared Canada\'s national summer sport in 1994, while ice hockey is the national winter sport. Lacrosse originated among Indigenous peoples of North America.' },
  { id: 'spo-20', category: 'sports', difficulty: 'easy', question: 'How many Grand Slam tennis tournaments are there each year?', answer: '4', options: ['3', '4', '5', '6'], explanation: 'The four Grand Slams are the Australian Open, French Open (Roland Garros), Wimbledon, and US Open. They are played on hardcourt, clay, grass, and hardcourt respectively.' },
  { id: 'spo-21', category: 'sports', difficulty: 'easy', question: 'What team did Michael Jordan play most of his career for?', answer: 'Chicago Bulls', options: ['Chicago Bulls', 'Washington Wizards', 'Los Angeles Lakers', 'New York Knicks'], explanation: 'Jordan won all six of his NBA championships with the Bulls (1991-93, 1996-98). He briefly retired to play minor league baseball before returning to the Bulls, and later played for the Washington Wizards.' },
  { id: 'spo-22', category: 'sports', difficulty: 'easy', question: 'What is the width of a regulation NBA basketball hoop in inches?', answer: '18 inches', options: ['16 inches', '18 inches', '20 inches', '22 inches'], explanation: 'The rim is 18 inches in diameter, mounted 10 feet above the floor. A standard basketball is about 9.4 inches in diameter, meaning nearly two balls could fit through the hoop at once.' },
  { id: 'spo-23', category: 'sports', difficulty: 'easy', question: 'What country hosted the 2016 Summer Olympics?', answer: 'Brazil', options: ['China', 'Brazil', 'United Kingdom', 'Japan'], explanation: 'The 2016 Olympics were held in Rio de Janeiro, making it the first South American city to host the Games. The United States led the medal count with 121 total medals.' },
  { id: 'spo-24', category: 'sports', difficulty: 'easy', question: 'What MLB team has won the most World Series titles?', answer: 'New York Yankees', options: ['St. Louis Cardinals', 'New York Yankees', 'Boston Red Sox', 'San Francisco Giants'], explanation: 'The Yankees have won 27 World Series championships, far more than any other team. The St. Louis Cardinals are second with 11 titles.' },
  { id: 'spo-25', category: 'sports', difficulty: 'easy', question: 'What is the regulation length of an NFL football field in yards?', answer: '100 yards', options: ['80 yards', '100 yards', '110 yards', '120 yards'], explanation: 'The playing field is 100 yards long with two 10-yard end zones, making the total field 120 yards. The field is 53 1/3 yards wide.' },
  { id: 'spo-26', category: 'sports', difficulty: 'easy', question: 'What swimmer has won the most Olympic gold medals in history?', answer: 'Michael Phelps', options: ['Mark Spitz', 'Michael Phelps', 'Ian Thorpe', 'Ryan Lochte'], explanation: 'Michael Phelps won 23 Olympic gold medals and 28 total medals across five Olympics (2000-2016). He won 8 gold medals at the 2008 Beijing Olympics alone, breaking Mark Spitz\'s record of 7 golds in one Games.' },
  { id: 'spo-27', category: 'sports', difficulty: 'easy', question: 'What sport uses a shuttlecock?', answer: 'Badminton', options: ['Tennis', 'Badminton', 'Squash', 'Table tennis'], explanation: 'A shuttlecock (or birdie) is a cone-shaped projectile with feathers or synthetic material. Badminton shuttlecocks can reach speeds over 300 mph, making it the fastest racket sport.' },
  { id: 'spo-28', category: 'sports', difficulty: 'easy', question: 'How many innings are in a regulation Major League Baseball game?', answer: '9', options: ['7', '8', '9', '10'], explanation: 'A regulation MLB game is 9 innings. If the home team is winning after the top of the 9th, the bottom of the 9th is not played. Extra innings are played if the score is tied.' },
  { id: 'spo-29', category: 'sports', difficulty: 'easy', question: 'What NFL team won the first Super Bowl?', answer: 'Green Bay Packers', options: ['Dallas Cowboys', 'Green Bay Packers', 'Pittsburgh Steelers', 'New York Giants'], explanation: 'The Packers beat the Kansas City Chiefs 35-10 in Super Bowl I on January 15, 1967. Coach Vince Lombardi led them to victories in both Super Bowl I and II. The Super Bowl trophy is named after him.' },
  { id: 'spo-30', category: 'sports', difficulty: 'easy', question: 'What is the name of the trophy awarded to the NHL champion?', answer: 'Stanley Cup', options: ['Lombardi Trophy', 'Stanley Cup', 'Commissioner\'s Trophy', 'Larry O\'Brien Trophy'], explanation: 'The Stanley Cup was donated by Lord Stanley of Preston, the Governor General of Canada, in 1893. It is the oldest professional sports trophy in North America and each winning player gets to spend a day with the Cup.' },
  { id: 'spo-31', category: 'sports', difficulty: 'easy', question: 'What jersey number did Wayne Gretzky wear?', answer: '99', options: ['9', '66', '87', '99'], explanation: 'Wayne Gretzky\'s number 99 was retired league-wide by the NHL in 2000, the only number so honored. He holds the record for most career goals (894) and assists (1,963) in NHL history.' },
  { id: 'spo-32', category: 'sports', difficulty: 'easy', question: 'What city is home to the Green Monster?', answer: 'Boston', options: ['New York', 'Boston', 'Chicago', 'Philadelphia'], explanation: 'The Green Monster is the 37-foot-2-inch left field wall at Fenway Park, home of the Boston Red Sox. Fenway Park, opened in 1912, is the oldest ballpark in Major League Baseball.' },
  { id: 'spo-33', category: 'sports', difficulty: 'easy', question: 'In soccer, what does a red card mean?', answer: 'Ejection from the game', options: ['Warning', 'Ejection from the game', 'Free kick awarded', 'Penalty kick awarded'], explanation: 'A red card results in immediate ejection and the team plays with one fewer player. Red and yellow cards were introduced at the 1970 FIFA World Cup by referee Ken Aston.' },
  { id: 'spo-34', category: 'sports', difficulty: 'easy', question: 'What legendary baseball player was known as "The Bambino"?', answer: 'Babe Ruth', options: ['Lou Gehrig', 'Babe Ruth', 'Joe DiMaggio', 'Ted Williams'], explanation: 'Babe Ruth hit 714 career home runs and was one of the first five players inducted into the Baseball Hall of Fame in 1936. He was sold from the Red Sox to the Yankees in 1920, beginning the "Curse of the Bambino."' },
  { id: 'spo-35', category: 'sports', difficulty: 'easy', question: 'How many players are on a soccer team on the field at one time?', answer: '11', options: ['9', '10', '11', '12'], explanation: 'Each team fields 11 players including the goalkeeper. A team must have at least 7 players to continue a match, and up to 3-5 substitutions are allowed depending on the competition.' },
  { id: 'spo-36', category: 'sports', difficulty: 'medium', question: 'What quarterback has won the most Super Bowl titles?', answer: 'Tom Brady', options: ['Joe Montana', 'Tom Brady', 'Terry Bradshaw', 'Peyton Manning'], explanation: 'Tom Brady won seven Super Bowls (XXXVI, XXXVIII, XXXIX, XLIX, LI, LIII, LV), six with New England and one with Tampa Bay. He was drafted in the sixth round as the 199th overall pick in 2000.' },
  { id: 'spo-37', category: 'sports', difficulty: 'medium', question: 'What is the only team to complete a perfect season in the NFL (including the Super Bowl)?', answer: '1972 Miami Dolphins', options: ['1985 Chicago Bears', '1972 Miami Dolphins', '2007 New England Patriots', '1984 San Francisco 49ers'], explanation: 'The 1972 Dolphins went 17-0, finishing with a Super Bowl VII victory over Washington. The 2007 Patriots went 16-0 in the regular season but lost to the New York Giants in Super Bowl XLII.' },
  { id: 'spo-38', category: 'sports', difficulty: 'medium', question: 'What is the distance of a marathon in miles?', answer: '26.2 miles', options: ['24.8 miles', '26.2 miles', '27.5 miles', '25.0 miles'], explanation: 'The official marathon distance is 26 miles and 385 yards (42.195 kilometers). This distance was standardized at the 1908 London Olympics to accommodate the British royal family\'s viewing convenience.' },
  { id: 'spo-39', category: 'sports', difficulty: 'medium', question: 'What NHL team has won the most Stanley Cup championships?', answer: 'Montreal Canadiens', options: ['Toronto Maple Leafs', 'Montreal Canadiens', 'Detroit Red Wings', 'Boston Bruins'], explanation: 'The Montreal Canadiens have won 24 Stanley Cups, the most of any NHL team. Their last championship was in 1993, the longest current drought among former champions with that many titles.' },
  { id: 'spo-40', category: 'sports', difficulty: 'medium', question: 'What is the name of the award given to the NFL\'s Most Valuable Player?', answer: 'AP Most Valuable Player Award', options: ['Heisman Trophy', 'AP Most Valuable Player Award', 'Lombardi Award', 'Bert Bell Award'], explanation: 'The Associated Press NFL MVP has been awarded since 1957. Peyton Manning won it a record five times. The Heisman Trophy is for college football\'s best player.' },
  { id: 'spo-41', category: 'sports', difficulty: 'medium', question: 'What city hosted the first modern Olympic Games in 1896?', answer: 'Athens', options: ['Paris', 'Athens', 'London', 'Rome'], explanation: 'The 1896 Athens Olympics featured 241 athletes from 14 nations competing in 43 events. Greece\'s Spyridon Louis won the marathon, becoming a national hero.' },
  { id: 'spo-42', category: 'sports', difficulty: 'medium', question: 'What golfer has won the most major championships?', answer: 'Jack Nicklaus', options: ['Tiger Woods', 'Jack Nicklaus', 'Arnold Palmer', 'Ben Hogan'], explanation: 'Jack Nicklaus won 18 major championships, three more than Tiger Woods (15). Known as "The Golden Bear," Nicklaus won his last major at age 46 at the 1986 Masters.' },
  { id: 'spo-43', category: 'sports', difficulty: 'medium', question: 'What is the only country to have played in every FIFA World Cup tournament?', answer: 'Brazil', options: ['Germany', 'Argentina', 'Brazil', 'Italy'], explanation: 'Brazil has appeared in all 22 World Cup tournaments since the inaugural event in 1930. They are also the most successful team with five titles.' },
  { id: 'spo-44', category: 'sports', difficulty: 'medium', question: 'What baseball player holds the all-time record for career home runs?', answer: 'Barry Bonds', options: ['Hank Aaron', 'Barry Bonds', 'Babe Ruth', 'Alex Rodriguez'], explanation: 'Barry Bonds hit 762 career home runs, surpassing Hank Aaron\'s record of 755 in 2007. Bonds also holds the single-season record with 73 home runs in 2001.' },
  { id: 'spo-45', category: 'sports', difficulty: 'medium', question: 'What country has won the most Olympic gold medals all-time (Summer Games)?', answer: 'United States', options: ['Soviet Union', 'United States', 'Great Britain', 'China'], explanation: 'The United States has won over 1,000 Summer Olympic gold medals, more than any other country. Track and field and swimming are traditionally their strongest events.' },
  { id: 'spo-46', category: 'sports', difficulty: 'medium', question: 'What is the Kentucky Derby\'s nickname?', answer: 'The Most Exciting Two Minutes in Sports', options: ['The Run for the Roses', 'The Most Exciting Two Minutes in Sports', 'The Sport of Kings', 'The Big Race'], explanation: 'The Kentucky Derby is called "The Most Exciting Two Minutes in Sports" because the race lasts approximately two minutes. It is also called "The Run for the Roses" because the winner receives a garland of 554 red roses.' },
  { id: 'spo-47', category: 'sports', difficulty: 'medium', question: 'What NBA team has won the most championships?', answer: 'Boston Celtics', options: ['Los Angeles Lakers', 'Boston Celtics', 'Chicago Bulls', 'Golden State Warriors'], explanation: 'The Boston Celtics have won 18 NBA championships, one more than the Los Angeles Lakers with 17. Bill Russell led the Celtics to 11 championships in 13 seasons.' },
  { id: 'spo-48', category: 'sports', difficulty: 'medium', question: 'What athlete won gold medals in both the 100m and 200m at three consecutive Olympics?', answer: 'Usain Bolt', options: ['Carl Lewis', 'Usain Bolt', 'Jesse Owens', 'Florence Griffith-Joyner'], explanation: 'Usain Bolt won both sprints at the 2008, 2012, and 2016 Olympics. His world records of 9.58 seconds (100m) and 19.19 seconds (200m), set in 2009, still stand.' },
  { id: 'spo-49', category: 'sports', difficulty: 'medium', question: 'What Formula 1 driver holds the record for most World Championships?', answer: 'Lewis Hamilton and Michael Schumacher (7 each)', options: ['Lewis Hamilton and Michael Schumacher (7 each)', 'Michael Schumacher (8)', 'Lewis Hamilton (8)', 'Ayrton Senna (5)'], explanation: 'Both Hamilton and Schumacher have won 7 World Drivers\' Championships as of 2024. Max Verstappen has been rapidly adding to his total and won four consecutive titles from 2021-2024.' },
  { id: 'spo-50', category: 'sports', difficulty: 'medium', question: 'What soccer player is the all-time leading scorer in FIFA World Cup history?', answer: 'Miroslav Klose', options: ['Ronaldo (R9)', 'Miroslav Klose', 'Pele', 'Just Fontaine'], explanation: 'Germany\'s Miroslav Klose scored 16 World Cup goals across four tournaments (2002-2014). He broke Ronaldo\'s previous record of 15 goals during the 2014 World Cup in Brazil.' },
  { id: 'spo-51', category: 'sports', difficulty: 'medium', question: 'What is the only NFL team to have no logo on their helmet?', answer: 'Cleveland Browns', options: ['Cleveland Browns', 'Cincinnati Bengals', 'Baltimore Ravens', 'Pittsburgh Steelers'], explanation: 'The Cleveland Browns helmet is plain orange with a brown-and-white stripe. The team was named after its first coach and general manager, Paul Brown, who is also the founder of the Cincinnati Bengals.' },
  { id: 'spo-52', category: 'sports', difficulty: 'medium', question: 'What tennis player has won the most Grand Slam singles titles (men\'s)?', answer: 'Novak Djokovic', options: ['Roger Federer', 'Rafael Nadal', 'Novak Djokovic', 'Pete Sampras'], explanation: 'Novak Djokovic has won 24 Grand Slam singles titles as of 2024, surpassing Nadal (22) and Federer (20). He is the only man to hold all four Grand Slam titles simultaneously twice.' },
  { id: 'spo-53', category: 'sports', difficulty: 'medium', question: 'What Heisman Trophy winner went on to star in movies and TV commercials for Hertz?', answer: 'O.J. Simpson', options: ['Bo Jackson', 'O.J. Simpson', 'Herschel Walker', 'Earl Campbell'], explanation: 'O.J. Simpson won the Heisman Trophy in 1968 as a running back at USC. He rushed for over 11,000 yards in the NFL and was the first player to rush for 2,000 yards in a single season (1973).' },
  { id: 'spo-54', category: 'sports', difficulty: 'medium', question: 'What is the name of the trophy awarded to the winner of the Masters golf tournament?', answer: 'Green Jacket', options: ['Claret Jug', 'Green Jacket', 'Wanamaker Trophy', 'Gold Medal'], explanation: 'Winners of the Masters receive a green jacket, a tradition started in 1949. The tournament is held annually at Augusta National Golf Club in Georgia, the only major played at the same course every year.' },
  { id: 'spo-55', category: 'sports', difficulty: 'medium', question: 'What is the record for consecutive games played in MLB, known as the "Iron Man" record?', answer: '2,632 games (Cal Ripken Jr.)', options: ['2,130 games (Lou Gehrig)', '2,632 games (Cal Ripken Jr.)', '2,500 games (Cal Ripken Jr.)', '2,800 games (Pete Rose)'], explanation: 'Cal Ripken Jr. broke Lou Gehrig\'s record of 2,130 consecutive games on September 6, 1995. Ripken\'s streak lasted from May 30, 1982 to September 19, 1998.' },
  { id: 'spo-56', category: 'sports', difficulty: 'medium', question: 'What college football team has won the most national championships?', answer: 'Alabama', options: ['Notre Dame', 'Alabama', 'Ohio State', 'USC'], explanation: 'Alabama claims the most national championships in college football history. Under coach Nick Saban, they won six national titles between 2009 and 2020.' },
  { id: 'spo-57', category: 'sports', difficulty: 'medium', question: 'What is the nickname of the New Zealand national rugby team?', answer: 'All Blacks', options: ['Springboks', 'All Blacks', 'Wallabies', 'Pumas'], explanation: 'The All Blacks are famous for performing the haka, a traditional Maori war dance, before each match. They have won the Rugby World Cup three times (1987, 2011, 2015).' },
  { id: 'spo-58', category: 'sports', difficulty: 'medium', question: 'What basketball player scored 100 points in a single NBA game?', answer: 'Wilt Chamberlain', options: ['Michael Jordan', 'Wilt Chamberlain', 'Kobe Bryant', 'LeBron James'], explanation: 'Wilt Chamberlain scored 100 points for the Philadelphia Warriors against the New York Knicks on March 2, 1962. No video of the game exists, only an audio recording. Kobe Bryant\'s 81 points in 2006 is the second-highest.' },
  { id: 'spo-59', category: 'sports', difficulty: 'medium', question: 'What country won the first FIFA World Cup in 1930?', answer: 'Uruguay', options: ['Brazil', 'Argentina', 'Uruguay', 'Italy'], explanation: 'Uruguay won the inaugural World Cup, held on their home soil in Montevideo. They beat Argentina 4-2 in the final. Only 13 teams participated, as many European nations declined due to the long sea journey.' },
  { id: 'spo-60', category: 'sports', difficulty: 'medium', question: 'What is the name of the award given to the best college basketball player in the NCAA?', answer: 'Naismith Award', options: ['Wooden Award', 'Naismith Award', 'Cousy Award', 'Robertson Trophy'], explanation: 'The Naismith Trophy, named after basketball inventor James Naismith, has been awarded since 1969. The John R. Wooden Award is another prestigious honor given to the best college basketball player.' },
  { id: 'spo-61', category: 'sports', difficulty: 'medium', question: 'What NFL stadium is known as "The Frozen Tundra"?', answer: 'Lambeau Field', options: ['Soldier Field', 'Lambeau Field', 'MetLife Stadium', 'Arrowhead Stadium'], explanation: 'Lambeau Field in Green Bay, Wisconsin earned this nickname due to its extremely cold temperatures during winter games. The famous "Ice Bowl" in 1967 was played in -13°F weather with a wind chill of -48°F.' },
  { id: 'spo-62', category: 'sports', difficulty: 'medium', question: 'What female tennis player has won the most Grand Slam singles titles?', answer: 'Margaret Court', options: ['Serena Williams', 'Margaret Court', 'Steffi Graf', 'Martina Navratilova'], explanation: 'Margaret Court won 24 Grand Slam singles titles, one more than Serena Williams\'s 23. However, many of Court\'s titles came before the Open Era began in 1968. Serena holds the Open Era record.' },
  { id: 'spo-63', category: 'sports', difficulty: 'medium', question: 'What is the only position in soccer allowed to use their hands within the penalty area?', answer: 'Goalkeeper', options: ['Goalkeeper', 'Defender', 'Sweeper', 'Libero'], explanation: 'The goalkeeper can handle the ball within their own 18-yard penalty area. If a goalkeeper handles the ball outside this area, it results in a free kick for the opposing team.' },
  { id: 'spo-64', category: 'sports', difficulty: 'medium', question: 'What heavyweight boxer retired undefeated with a 49-0 record in 1956?', answer: 'Rocky Marciano', options: ['Joe Louis', 'Rocky Marciano', 'Muhammad Ali', 'Floyd Mayweather'], explanation: 'Rocky Marciano is the only heavyweight champion to retire undefeated. Floyd Mayweather later retired 50-0 but was never the undisputed heavyweight champion. Marciano won 43 of his 49 fights by knockout.' },
  { id: 'spo-65', category: 'sports', difficulty: 'medium', question: 'What MLB pitcher holds the record for the most career strikeouts?', answer: 'Nolan Ryan', options: ['Randy Johnson', 'Nolan Ryan', 'Roger Clemens', 'Steve Carlton'], explanation: 'Nolan Ryan recorded 5,714 career strikeouts, nearly 900 more than second-place Randy Johnson (4,875). Ryan also threw a record seven no-hitters during his 27-year career.' },
  { id: 'spo-66', category: 'sports', difficulty: 'medium', question: 'What jersey number did Kobe Bryant wear for most of his career with the Lakers?', answer: '24', options: ['8', '24', '33', '32'], explanation: 'Kobe wore #8 from 1996 to 2006 and switched to #24 for the remainder of his career. The Lakers retired both numbers, making Kobe the only player in franchise history to have two numbers retired.' },
  { id: 'spo-67', category: 'sports', difficulty: 'medium', question: 'In what year were women first allowed to compete in the modern Olympic Games?', answer: '1900', options: ['1896', '1900', '1908', '1920'], explanation: 'Women first competed at the 1900 Paris Olympics in five sports: tennis, sailing, croquet, equestrian, and golf. Charlotte Cooper became the first female Olympic champion, winning tennis singles.' },
  { id: 'spo-68', category: 'sports', difficulty: 'medium', question: 'What is the name of the annual college football game between Army and Navy?', answer: 'Army-Navy Game', options: ['The Big Game', 'Army-Navy Game', 'The Service Classic', 'The Rivalry'], explanation: 'The Army-Navy Game is one of the most storied rivalries in college football, played annually since 1890. The President of the United States traditionally attends and switches sides at halftime.' },
  { id: 'spo-69', category: 'sports', difficulty: 'medium', question: 'What NHL player is known as "The Great One"?', answer: 'Wayne Gretzky', options: ['Mario Lemieux', 'Wayne Gretzky', 'Bobby Orr', 'Gordie Howe'], explanation: 'Wayne Gretzky holds 61 NHL records. Even if you removed all of his goals, he would still be the all-time points leader on assists alone (1,963 assists vs. the second-place total points leader).' },
  { id: 'spo-70', category: 'sports', difficulty: 'medium', question: 'What is the term for three consecutive strikes in bowling?', answer: 'Turkey', options: ['Hat trick', 'Turkey', 'Triple', 'Trifecta'], explanation: 'A turkey (three strikes in a row) got its name from the late 1800s when bowling alleys would award a turkey to players who achieved the feat during holiday tournaments. Four in a row is called a "four-bagger."' },
  { id: 'spo-71', category: 'sports', difficulty: 'medium', question: 'What soccer club has won the most UEFA Champions League titles?', answer: 'Real Madrid', options: ['AC Milan', 'Real Madrid', 'Barcelona', 'Bayern Munich'], explanation: 'Real Madrid has won the Champions League/European Cup 15 times. They won the first five tournaments consecutively from 1956 to 1960 and added several more in the 2010s and 2020s.' },
  { id: 'spo-72', category: 'sports', difficulty: 'medium', question: 'What is the name of the trophy given to the Super Bowl MVP?', answer: 'Pete Rozelle Trophy', options: ['Vince Lombardi Trophy', 'Pete Rozelle Trophy', 'George Halas Trophy', 'Walter Payton Award'], explanation: 'The Super Bowl MVP award is named after Pete Rozelle, the NFL commissioner who oversaw the first Super Bowl. The Vince Lombardi Trophy is the team championship trophy, not the MVP award.' },
  { id: 'spo-73', category: 'sports', difficulty: 'medium', question: 'What track and field athlete won four gold medals at the 1936 Berlin Olympics?', answer: 'Jesse Owens', options: ['Jesse Owens', 'Carl Lewis', 'Jim Thorpe', 'Paavo Nurmi'], explanation: 'Jesse Owens won gold in the 100m, 200m, long jump, and 4x100m relay, defying Adolf Hitler\'s claims of Aryan supremacy. Carl Lewis matched Owens\'s four-gold feat at the 1984 Los Angeles Olympics.' },
  { id: 'spo-74', category: 'sports', difficulty: 'medium', question: 'What is the only Grand Slam tennis tournament played on clay?', answer: 'French Open (Roland Garros)', options: ['Australian Open', 'French Open (Roland Garros)', 'Wimbledon', 'US Open'], explanation: 'The French Open is played on red clay courts at Stade Roland Garros in Paris. Rafael Nadal has won the tournament a record 14 times, earning the nickname "King of Clay."' },
  { id: 'spo-75', category: 'sports', difficulty: 'medium', question: 'What baseball player broke the color barrier in MLB in 1947?', answer: 'Jackie Robinson', options: ['Satchel Paige', 'Jackie Robinson', 'Larry Doby', 'Willie Mays'], explanation: 'Jackie Robinson debuted for the Brooklyn Dodgers on April 15, 1947. His number 42 was retired across all MLB teams in 1997. April 15 is now celebrated as Jackie Robinson Day, when all players wear #42.' },
  { id: 'spo-76', category: 'sports', difficulty: 'medium', question: 'What is the diameter of a basketball hoop in relation to the ball?', answer: 'About twice the ball\'s diameter', options: ['Exactly the ball\'s diameter', 'About 1.5 times the ball\'s diameter', 'About twice the ball\'s diameter', 'About 3 times the ball\'s diameter'], explanation: 'The rim is 18 inches in diameter while a men\'s basketball is about 9.4 inches in diameter. This means the ball has about 4 inches of clearance on each side when centered perfectly.' },
  { id: 'spo-77', category: 'sports', difficulty: 'medium', question: 'What NFL team plays its home games at Arrowhead Stadium?', answer: 'Kansas City Chiefs', options: ['Kansas City Chiefs', 'Denver Broncos', 'Las Vegas Raiders', 'Dallas Cowboys'], explanation: 'Arrowhead Stadium opened in 1972 and held the Guinness World Record for loudest crowd roar at 142.2 decibels, set in 2014. It has a seating capacity of about 76,000.' },
  { id: 'spo-78', category: 'sports', difficulty: 'medium', question: 'Who holds the NBA record for most points scored in a career?', answer: 'LeBron James', options: ['Kareem Abdul-Jabbar', 'LeBron James', 'Karl Malone', 'Michael Jordan'], explanation: 'LeBron James surpassed Kareem Abdul-Jabbar\'s record of 38,387 points on February 7, 2023. He continues to add to his total. Kareem held the record for nearly 39 years.' },
  { id: 'spo-79', category: 'sports', difficulty: 'medium', question: 'What sport was invented by James Naismith in 1891?', answer: 'Basketball', options: ['Volleyball', 'Basketball', 'Baseball', 'Football'], explanation: 'James Naismith invented basketball at a YMCA training school in Springfield, Massachusetts. The first game used a soccer ball and two peach baskets as goals. Players had to climb a ladder to retrieve the ball after each basket.' },
  { id: 'spo-80', category: 'sports', difficulty: 'medium', question: 'What is the record for most passing touchdowns in a single NFL season?', answer: '55 (Peyton Manning)', options: ['50 (Tom Brady)', '55 (Peyton Manning)', '52 (Patrick Mahomes)', '48 (Dan Marino)'], explanation: 'Peyton Manning threw 55 touchdown passes for the Denver Broncos in 2013. He broke Tom Brady\'s record of 50, set in 2007. Dan Marino\'s 48 in 1984 stood as the record for 20 years.' },
  { id: 'spo-81', category: 'sports', difficulty: 'medium', question: 'What is the Masters golf tournament\'s signature sandwich sold at concession stands?', answer: 'Pimento cheese sandwich', options: ['Club sandwich', 'Pimento cheese sandwich', 'Ham and cheese sandwich', 'BBQ pulled pork sandwich'], explanation: 'The pimento cheese sandwich is famous at Augusta National for both its taste and its remarkably low price (around $1.50). The Masters is known for keeping its concession prices far below typical sporting event costs.' },
  { id: 'spo-82', category: 'sports', difficulty: 'medium', question: 'What boxer held the heavyweight title for the longest continuous reign?', answer: 'Joe Louis', options: ['Muhammad Ali', 'Joe Louis', 'Larry Holmes', 'Lennox Lewis'], explanation: 'Joe Louis held the heavyweight title for 11 years and 252 days (1937-1949), making 25 successful title defenses. He was nicknamed the "Brown Bomber" and is widely considered one of the greatest heavyweights ever.' },
  { id: 'spo-83', category: 'sports', difficulty: 'medium', question: 'What was the "Miracle on Ice"?', answer: 'USA hockey team beating the Soviet Union at the 1980 Olympics', options: ['USA hockey team beating the Soviet Union at the 1980 Olympics', 'Canada winning gold in hockey at the 2010 Olympics', 'USA beating England in the 1950 World Cup', 'The 1994 Winter Olympics figure skating controversy'], explanation: 'The U.S. team of mostly college players defeated the heavily favored Soviet team 4-3 on February 22, 1980, at Lake Placid. The USA went on to beat Finland to win the gold medal. Al Michaels\' call "Do you believe in miracles?" became iconic.' },
  { id: 'spo-84', category: 'sports', difficulty: 'medium', question: 'What is the name of the championship trophy in the NBA?', answer: 'Larry O\'Brien Championship Trophy', options: ['James Naismith Trophy', 'Larry O\'Brien Championship Trophy', 'Maurice Podoloff Trophy', 'Red Auerbach Trophy'], explanation: 'The trophy was renamed in 1984 after former NBA commissioner Larry O\'Brien. It is made of sterling silver, stands about 2 feet tall, weighs about 14.5 pounds, and features a basketball about to enter a net.' },
  { id: 'spo-85', category: 'sports', difficulty: 'medium', question: 'What pitcher threw a perfect game in the World Series?', answer: 'Don Larsen', options: ['Sandy Koufax', 'Don Larsen', 'Nolan Ryan', 'Randy Johnson'], explanation: 'Don Larsen of the New York Yankees threw the only perfect game in World Series history on October 8, 1956, against the Brooklyn Dodgers. He retired all 27 batters he faced in a 2-0 victory.' },
  { id: 'spo-86', category: 'sports', difficulty: 'medium', question: 'What city\'s NBA team is called the "76ers"?', answer: 'Philadelphia', options: ['Boston', 'Philadelphia', 'New York', 'Washington'], explanation: 'The Philadelphia 76ers are named after the year 1776, when the Declaration of Independence was signed in Philadelphia. The franchise was originally the Syracuse Nationals before relocating in 1963.' },
  { id: 'spo-87', category: 'sports', difficulty: 'medium', question: 'What is the oldest rivalry in international soccer?', answer: 'England vs. Scotland', options: ['England vs. Scotland', 'Brazil vs. Argentina', 'Spain vs. Portugal', 'Germany vs. Netherlands'], explanation: 'The first official international football match was played between England and Scotland on November 30, 1872, in Glasgow, ending 0-0. The fixture is known as the oldest international rivalry in football.' },
  { id: 'spo-88', category: 'sports', difficulty: 'medium', question: 'What is a "triple-double" in basketball?', answer: 'Recording double digits in three statistical categories', options: ['Scoring 30+ points in three consecutive games', 'Recording double digits in three statistical categories', 'Making three three-pointers in a row', 'Scoring from all three zones on the court'], explanation: 'A triple-double typically involves points, rebounds, and assists, but can include steals or blocks. Russell Westbrook holds the NBA record for most career triple-doubles, surpassing Oscar Robertson.' },
  { id: 'spo-89', category: 'sports', difficulty: 'medium', question: 'What country hosted the 2022 FIFA World Cup?', answer: 'Qatar', options: ['United Arab Emirates', 'Qatar', 'Saudi Arabia', 'Kuwait'], explanation: 'Qatar 2022 was the first World Cup held in the Middle East and the first held in November-December instead of the usual June-July window. Argentina won the tournament, with Lionel Messi leading them to victory.' },
  { id: 'spo-90', category: 'sports', difficulty: 'medium', question: 'What NFL team has the most Super Bowl appearances?', answer: 'New England Patriots', options: ['Dallas Cowboys', 'New England Patriots', 'Pittsburgh Steelers', 'San Francisco 49ers'], explanation: 'The New England Patriots have made 11 Super Bowl appearances, winning 6. The Dallas Cowboys and Pittsburgh Steelers have each made 8 appearances.' },
  { id: 'spo-91', category: 'sports', difficulty: 'hard', question: 'What is the only country to have won the FIFA World Cup on three different continents?', answer: 'Brazil', options: ['Germany', 'Brazil', 'Italy', 'Argentina'], explanation: 'Brazil won in Europe (1958 Sweden), South America (1962 Chile), and North America (1970 Mexico, 1994 USA). No other country has won the tournament on more than two continents.' },
  { id: 'spo-92', category: 'sports', difficulty: 'hard', question: 'What was the longest tennis match in history by duration?', answer: 'Isner vs. Mahut at Wimbledon 2010 (11 hours 5 minutes)', options: ['Federer vs. Nadal Wimbledon 2008 (5 hours)', 'Isner vs. Mahut at Wimbledon 2010 (11 hours 5 minutes)', 'Djokovic vs. Nadal Australian Open 2012 (6 hours)', 'Anderson vs. Isner Wimbledon 2018 (7 hours)'], explanation: 'John Isner defeated Nicolas Mahut 70-68 in the fifth set over three days in 2010. The match lasted 11 hours and 5 minutes. Wimbledon has since introduced a final-set tiebreaker to prevent such occurrences.' },
  { id: 'spo-93', category: 'sports', difficulty: 'hard', question: 'What is the Cy Young Award given for?', answer: 'Best pitcher in each MLB league', options: ['Best overall player in MLB', 'Best pitcher in each MLB league', 'Best rookie pitcher in MLB', 'Most strikeouts in a season'], explanation: 'The Cy Young Award has been given since 1956, named after pitcher Cy Young who holds the record for most career wins (511). Since 1967, the award has been given to the best pitcher in both the American and National League.' },
  { id: 'spo-94', category: 'sports', difficulty: 'hard', question: 'What horse racing event completes the Triple Crown along with the Kentucky Derby and Preakness Stakes?', answer: 'Belmont Stakes', options: ['Breeders\' Cup Classic', 'Belmont Stakes', 'Travers Stakes', 'Arlington Million'], explanation: 'The Belmont Stakes is the longest of the three races at 1.5 miles and is often called "The Test of the Champion." Only 13 horses have won the Triple Crown, with Justify being the most recent in 2018.' },
  { id: 'spo-95', category: 'sports', difficulty: 'hard', question: 'What NFL quarterback threw for the most yards in a single season?', answer: 'Peyton Manning (5,477 yards in 2013)', options: ['Drew Brees (5,476 yards in 2011)', 'Peyton Manning (5,477 yards in 2013)', 'Tom Brady (5,316 yards in 2011)', 'Patrick Mahomes (5,250 yards in 2018)'], explanation: 'Manning edged out Brees by just one yard for the record. Manning set this record during the same 2013 season he threw 55 touchdown passes. Both records were set with the Denver Broncos.' },
  { id: 'spo-96', category: 'sports', difficulty: 'hard', question: 'What NBA team went 72-10 in the regular season and won the championship?', answer: '1995-96 Chicago Bulls', options: ['2015-16 Golden State Warriors', '1995-96 Chicago Bulls', '1971-72 Los Angeles Lakers', '2016-17 Golden State Warriors'], explanation: 'The 1995-96 Bulls went 72-10 and won the NBA championship. The 2015-16 Warriors broke the regular season record with 73 wins but lost in the Finals. The Bulls\' 72-10 championship season remains the gold standard.' },
  { id: 'spo-97', category: 'sports', difficulty: 'hard', question: 'What is the "Death Line" in rugby?', answer: 'There is no "Death Line" in rugby — it\'s called the try line or goal line', options: ['The halfway line', 'There is no "Death Line" in rugby — it\'s called the try line or goal line', 'The 22-meter line', 'The dead-ball line'], explanation: 'The dead-ball line marks the end of the in-goal area, beyond which the ball is out of play. The try line (goal line) is where tries are scored. The 22-meter line is used for dropouts.' },
  { id: 'spo-98', category: 'sports', difficulty: 'hard', question: 'What boxer was the first undisputed heavyweight champion under the Queensberry Rules?', answer: 'James J. Corbett', options: ['John L. Sullivan', 'James J. Corbett', 'Bob Fitzsimmons', 'Jim Jeffries'], explanation: 'Corbett defeated John L. Sullivan in 1892 in the first heavyweight title fight under Marquess of Queensberry Rules, which introduced gloves and three-minute rounds. Sullivan had been the last bare-knuckle champion.' },
  { id: 'spo-99', category: 'sports', difficulty: 'hard', question: 'What is the lowest score ever recorded in a single round at the Masters?', answer: '63', options: ['61', '62', '63', '64'], explanation: 'A 63 has been shot at the Masters multiple times, first by Nick Price in 1986. The course record of 63 has been matched but never broken. Augusta National\'s difficulty makes sub-64 rounds extremely rare.' },
  { id: 'spo-100', category: 'sports', difficulty: 'hard', question: 'What MLB team went 108 years between World Series titles (1908-2016)?', answer: 'Chicago Cubs', options: ['Boston Red Sox', 'Chicago Cubs', 'Cleveland Indians', 'Chicago White Sox'], explanation: 'The Cubs finally broke their championship drought by defeating the Cleveland Indians in a dramatic seven-game 2016 World Series. Game 7 went to extra innings, and the Cubs won 8-7 in 10 innings.' },
  { id: 'spo-101', category: 'sports', difficulty: 'hard', question: 'What is the only Winter Olympic sport in which the United States has never won a medal?', answer: 'Biathlon', options: ['Biathlon', 'Cross-country skiing', 'Nordic combined', 'Ski jumping'], explanation: 'Despite competing in Olympic biathlon since 1960, the United States has never won an Olympic medal in the sport. The best individual finish was Deedra Irwin\'s 7th place at the 2022 Beijing Olympics.' },
  { id: 'spo-102', category: 'sports', difficulty: 'hard', question: 'What is the record for most consecutive NBA championships won?', answer: '8 (Boston Celtics, 1959-1966)', options: ['6 (Chicago Bulls, 1991-1998)', '8 (Boston Celtics, 1959-1966)', '5 (Los Angeles Lakers, 1949-1953)', '3 (Los Angeles Lakers, 2000-2002)'], explanation: 'The Boston Celtics won 8 straight titles from 1959 to 1966, led by Bill Russell and coach Red Auerbach. This streak is widely considered the most dominant run in professional sports history.' },
  { id: 'spo-103', category: 'sports', difficulty: 'hard', question: 'What golfer won the 1997 Masters by a record 12 strokes at age 21?', answer: 'Tiger Woods', options: ['Phil Mickelson', 'Tiger Woods', 'Ernie Els', 'Fred Couples'], explanation: 'Tiger Woods shot a record 18-under-par 270 to win his first major championship. He was the youngest Masters champion and the first African American and Asian American to win the tournament.' },
  { id: 'spo-104', category: 'sports', difficulty: 'hard', question: 'What is the name of the formation in American football with no players in the backfield except the quarterback?', answer: 'Empty backfield', options: ['Shotgun formation', 'Empty backfield', 'Spread formation', 'I-formation'], explanation: 'The empty backfield (or "empty set") formation has the quarterback as the sole player in the backfield, with all five eligible receivers split out wide. The shotgun describes the QB\'s alignment several yards behind center but can still include running backs.' },
  { id: 'spo-105', category: 'sports', difficulty: 'hard', question: 'What NFL team relocated from St. Louis back to Los Angeles in 2016?', answer: 'Rams', options: ['Chargers', 'Rams', 'Raiders', 'Cardinals'], explanation: 'The Rams played in Los Angeles from 1946-1994, moved to St. Louis, then returned to LA in 2016. They now play at SoFi Stadium in Inglewood, California, which they share with the Chargers.' },
  { id: 'spo-106', category: 'sports', difficulty: 'hard', question: 'Who was the first African American to win the Heisman Trophy?', answer: 'Ernie Davis', options: ['Jim Brown', 'Ernie Davis', 'O.J. Simpson', 'Archie Griffin'], explanation: 'Ernie Davis of Syracuse University won the Heisman in 1961. Tragically, he was diagnosed with leukemia and passed away in 1963 at age 23, never playing a professional game. His story was told in the film "The Express."' },
  { id: 'spo-107', category: 'sports', difficulty: 'hard', question: 'What is the record for most goals scored in a single World Cup tournament by one player?', answer: '13 (Just Fontaine, 1958)', options: ['11 (Sandor Kocsis, 1954)', '13 (Just Fontaine, 1958)', '10 (Gerd Muller, 1970)', '8 (Ronaldo, 2002)'], explanation: 'France\'s Just Fontaine scored 13 goals in 6 matches at the 1958 World Cup in Sweden. This record has stood for over 65 years and is considered one of the most unbreakable records in football.' },
  { id: 'spo-108', category: 'sports', difficulty: 'hard', question: 'What Formula 1 circuit is known as "The Temple of Speed"?', answer: 'Monza', options: ['Silverstone', 'Monza', 'Monaco', 'Spa-Francorchamps'], explanation: 'Autodromo Nazionale di Monza in Italy has hosted F1 since the championship began in 1950. It features long straights that produce some of the highest speeds in F1, regularly exceeding 220 mph.' },
  { id: 'spo-109', category: 'sports', difficulty: 'hard', question: 'What pitcher threw a no-hitter in his first MLB start?', answer: 'Bobo Holloman', options: ['Bobo Holloman', 'Wilson Alvarez', 'Burt Hooton', 'Clay Buchholz'], explanation: 'Bobo Holloman of the St. Louis Browns threw a no-hitter on May 6, 1953, in his first major league start. He won only two more games that season and never pitched in the majors again after 1953.' },
  { id: 'spo-110', category: 'sports', difficulty: 'hard', question: 'What Olympic gymnast scored the first perfect 10 in Olympic history?', answer: 'Nadia Comaneci', options: ['Mary Lou Retton', 'Nadia Comaneci', 'Olga Korbut', 'Simone Biles'], explanation: 'Nadia Comaneci of Romania scored the first perfect 10 on the uneven bars at the 1976 Montreal Olympics at age 14. The scoreboard could only display up to 9.99, so her 10.00 was shown as 1.00.' },
  { id: 'spo-111', category: 'sports', difficulty: 'hard', question: 'What is the only player to win the Heisman Trophy twice?', answer: 'Archie Griffin', options: ['Herschel Walker', 'Archie Griffin', 'Tim Tebow', 'Bo Jackson'], explanation: 'Archie Griffin of Ohio State won the Heisman Trophy in both 1974 and 1975. No other player has won it more than once. Griffin rushed for over 5,000 yards in his college career.' },
  { id: 'spo-112', category: 'sports', difficulty: 'hard', question: 'What is the oldest existing trophy in international sports?', answer: 'America\'s Cup (sailing)', options: ['The Ashes (cricket)', 'America\'s Cup (sailing)', 'Stanley Cup (hockey)', 'Davis Cup (tennis)'], explanation: 'The America\'s Cup dates to 1851, when the schooner America won a race around the Isle of Wight. The New York Yacht Club held the trophy for 132 years (1851-1983) until Australia II finally won it.' },
  { id: 'spo-113', category: 'sports', difficulty: 'hard', question: 'What NFL running back holds the single-game rushing record with 296 yards?', answer: 'Adrian Peterson', options: ['Jamal Lewis', 'Adrian Peterson', 'Barry Sanders', 'Eric Dickerson'], explanation: 'Adrian Peterson rushed for 296 yards against the San Diego Chargers on November 4, 2007. He broke Jamal Lewis\'s previous record of 295 yards. Peterson went on to rush for 2,097 yards that season.' },
  { id: 'spo-114', category: 'sports', difficulty: 'hard', question: 'What was the first sport to be played on the moon?', answer: 'Golf', options: ['Golf', 'Javelin', 'Baseball', 'Football'], explanation: 'Astronaut Alan Shepard hit two golf balls on the moon during the Apollo 14 mission on February 6, 1971. He used a makeshift 6-iron attached to a lunar sample scoop handle.' },
  { id: 'spo-115', category: 'sports', difficulty: 'hard', question: 'What NBA team holds the record for the longest winning streak in a single season?', answer: 'Los Angeles Lakers (33 games, 1971-72)', options: ['Golden State Warriors (28 games, 2014-15)', 'Los Angeles Lakers (33 games, 1971-72)', 'Miami Heat (27 games, 2012-13)', 'Houston Rockets (22 games, 2007-08)'], explanation: 'The 1971-72 Lakers won 33 consecutive games from November 5, 1971 to January 7, 1972. The team went on to finish 69-13 and win the NBA championship.' },
  { id: 'spo-116', category: 'sports', difficulty: 'hard', question: 'What MLB player has the longest hitting streak?', answer: 'Joe DiMaggio (56 games)', options: ['Pete Rose (44 games)', 'Joe DiMaggio (56 games)', 'Ted Williams (49 games)', 'Ty Cobb (40 games)'], explanation: 'Joe DiMaggio hit safely in 56 consecutive games in 1941, a record many consider unbreakable. Pete Rose came closest with a 44-game streak in 1978. During his streak, DiMaggio batted .408 with 15 home runs.' },
  { id: 'spo-117', category: 'sports', difficulty: 'hard', question: 'What country has won the most FIFA Women\'s World Cup titles?', answer: 'United States', options: ['Germany', 'United States', 'Japan', 'Norway'], explanation: 'The U.S. Women\'s National Team has won the World Cup four times (1991, 1999, 2015, 2019). They won the inaugural tournament in 1991 in China. Germany has won twice (2003, 2007).' },
  { id: 'spo-118', category: 'sports', difficulty: 'hard', question: 'What is the highest-scoring NFL game in history?', answer: 'Washington 72, New York Giants 41 (1966)', options: ['Washington 72, New York Giants 41 (1966)', 'Cincinnati 58, Cleveland 48 (2004)', 'Chicago Bears 73, Washington 0 (1940)', 'New Orleans 52, New York Giants 49 (2015)'], explanation: 'The Washington vs. Giants game on November 27, 1966, produced 113 total points. The 73-0 Bears victory in the 1940 NFL Championship is the most lopsided game but had fewer total points at 73.' },
  { id: 'spo-119', category: 'sports', difficulty: 'hard', question: 'What is the name of the trophy awarded to the winner of the PGA Championship?', answer: 'Wanamaker Trophy', options: ['Claret Jug', 'Wanamaker Trophy', 'Havemeyer Trophy', 'Gold Medal'], explanation: 'The Wanamaker Trophy is named after Rodman Wanamaker, who organized the first PGA Championship in 1916. The Claret Jug is awarded at The Open Championship (British Open), and the Havemeyer Trophy goes to the U.S. Amateur champion.' },
  { id: 'spo-120', category: 'sports', difficulty: 'hard', question: 'What Olympic sport was removed after the 2008 Beijing Games and returned for the 2020 Tokyo Games?', answer: 'Baseball/Softball', options: ['Baseball/Softball', 'Wrestling', 'Golf', 'Karate'], explanation: 'Baseball and softball were removed after 2008 and returned for Tokyo 2020. Both sports were voted out by the IOC in 2005, then reinstated as additional sports for the Tokyo Olympics. They were dropped again for 2024 Paris but are expected to return for 2028 Los Angeles.' },
  { id: 'spo-121', category: 'sports', difficulty: 'hard', question: 'What is the only team to come back from a 3-0 series deficit to win the Stanley Cup Finals?', answer: '1942 Toronto Maple Leafs', options: ['1942 Toronto Maple Leafs', '1975 New York Islanders', '2004 Tampa Bay Lightning', '1971 Montreal Canadiens'], explanation: 'The 1942 Toronto Maple Leafs are the only team to come back from a 3-0 deficit to win the Stanley Cup Finals, defeating the Detroit Red Wings in seven games. Coach Hap Day benched several regulars for Game 4, sparking the historic comeback.' },
  { id: 'spo-122', category: 'sports', difficulty: 'hard', question: 'What is the highest individual score in a Test cricket innings?', answer: '400 not out (Brian Lara)', options: ['375 (Brian Lara)', '400 not out (Brian Lara)', '380 (Matthew Hayden)', '365 not out (Garfield Sobers)'], explanation: 'Brian Lara of the West Indies scored 400 not out against England in 2004 in Antigua. He also previously held the record with 375 against England in 1994. The innings lasted 778 minutes.' },
  { id: 'spo-123', category: 'sports', difficulty: 'hard', question: 'What driver has the most wins in Indianapolis 500 history?', answer: 'A.J. Foyt, Al Unser, Rick Mears, and Helio Castroneves (4 wins each)', options: ['Mario Andretti (3 wins)', 'A.J. Foyt, Al Unser, Rick Mears, and Helio Castroneves (4 wins each)', 'A.J. Foyt (5 wins)', 'Al Unser (5 wins)'], explanation: 'Four drivers share the record with four Indy 500 victories each. Helio Castroneves became the fourth to join this exclusive club in 2021. No driver has ever won five times.' },
  { id: 'spo-124', category: 'sports', difficulty: 'hard', question: 'What is the only position in American football that is eligible to be awarded the Heisman Trophy but has never won it?', answer: 'Offensive lineman', options: ['Kicker', 'Offensive lineman', 'Punter', 'Long snapper'], explanation: 'While any position is technically eligible, no offensive lineman has won the Heisman. The award heavily favors skill positions; running backs and quarterbacks have won the vast majority. The closest a lineman came was in the early decades of the award.' },
  { id: 'spo-125', category: 'sports', difficulty: 'hard', question: 'What is the longest field goal in NFL history?', answer: '66 yards (Justin Tucker, 2021)', options: ['64 yards (Matt Prater, 2013)', '66 yards (Justin Tucker, 2021)', '63 yards (Tom Dempsey, 1970)', '65 yards (Brett Maher, 2019)'], explanation: 'Justin Tucker of the Baltimore Ravens kicked a 66-yard field goal against the Detroit Lions on September 26, 2021, as time expired. The ball bounced off the crossbar and through the uprights. Matt Prater\'s 64-yarder in 2013 was the previous record.' },
]
